-color: #f8f9fa;\r\n    min-height: 100vh;\r\n}\r\n\r\n.dashboard-header {\r\n    margin-bottom: 32px;\r\n    display: flex;\r\n    justify-content: space-between;\r\n    align-items: center;\r\n}\r\n\r\n.dashboard-title {\r\n    font-weight: 800;\r\n    color: #1a1a1a;\r\n    font-size: 2rem;\r\n    letter-spacing: -0.5px;\r\n}\r\n\r\n.kpi-grid {\r\n    display: grid;\r\n    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\r\n    gap: 24px;\r\n    margin-bottom: 32px;\r\n}\r\n\r\n.kpi-card {\r\n    padding: 24px;\r\n    border-radius: 16px;\r\n    background: white;\r\n    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);\r\n    transition: transform 0.2s ease, box-shadow 0.2s ease;\r\n    border: 1px solid rgba(0, 0, 0, 0.05);\r\n    display: flex;\r\n    flex-direction: column;\r\n    justify-content: space-between;\r\n    min-height: 140px;\r\n}\r\n\r\n.kpi-card:hover {\r\n    transform: translateY(-4px);\r\n    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);\r\n}\r\n\r\n.kpi-icon-wrapper {\r\n    width: 48px;\r\n    height: 48px;\r\n    border-radius: 12px;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    margin-bottom: 16px;\r\n}\r\n\r\n.kpi-label {\r\n    color: #6b7280;\r\n    font-size: 0.875rem;\r\n    font-weight: 600;\r\n    text-transform: uppercase;\r\n    letter-spacing: 0.025em;\r\n}\r\n\r\n.kpi-value {\r\n    color: #111827;\r\n    font-size: 1.5rem;\r\n    font-weight: 700;\r\n    margin-top: 4px;\r\n}\r\n\r\n.kpi-trend {\r\n    font-size: 0.75rem;\r\n    margin-top: 8px;\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 4px;\r\n}\r\n\r\n.trend-up {\r\n    color: #10b981;\r\n}\r\n\r\n.trend-down {\r\n    color: #ef4444;\r\n}\r\n\r\n/* Main Content Grid */\r\n.main-grid {\r\n    display: grid;\r\n    grid-template-columns: 2fr 1fr;\r\n    gap: 24px;\r\n}\r\n\r\n.chart-section,\r\n.activity-section,\r\n.quick-links-section {\r\n    background: white;\r\n    padding: 24px;\r\n    border-radius: 16px;\r\n    border: 1px solid rgba(0, 0, 0, 0.05);\r\n    box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.1);\r\n}\r\n\r\n.section-title {\r\n    font-size: 1.125rem;\r\n    font-weight: 700;\r\n    color: #111827;\r\n    margin-bottom: 20px;\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 8px;\r\n}\r\n\r\n/* Timeline Stylings */\r\n.activity-item {\r\n    display: flex;\r\n    gap: 16px;\r\n    padding: 12px 0;\r\n    border-bottom: 1px solid #f3f4f6;\r\n}\r\n\r\n.activity-item:last-child {\r\n    border-bottom: none;\r\n}\r\n\r\n.activity-point {\r\n    width: 10px;\r\n    height: 10px;\r\n    border-radius: 50%;\r\n    margin-top: 6px;\r\n}\r\n\r\n.activity-content {\r\n    flex: 1;\r\n}\r\n\r\n.activity-text {\r\n    font-size: 0.875rem;\r\n    color: #374151;\r\n}\r\n\r\n.activity-time {\r\n    font-size: 0.75rem;\r\n    color: #9ca3af;\r\n    margin-top: 2px;\r\n}\r\n\r\n/* Quick Action Buttons */\r\n.quick-action-grid {\r\n    display: grid;\r\n    grid-template-columns: 1fr 1fr;\r\n    gap: 12px;\r\n}\r\n\r\n.action-btn {\r\n    display: flex;\r\n    flex-direction: column;\r\n    align-items: center;\r\n    gap: 8px;\r\n    padding: 16px;\r\n    border-radius: 12px;\r\n    border: 1px solid #e5e7eb;\r\n    background: #f9fafb;\r\n    color: #4b5563;\r\n    transition: all 0.2s ease;\r\n    cursor: pointer;\r\n    font-weight: 500;\r\n    font-size: 0.875rem;\r\n}\r\n\r\n.action-btn:hover {\r\n    background: #30368a;\r\n    color: white;\r\n    border-color: #30368a;\r\n    transform: translateY(-2px);\r\n}\r\n\r\n/* Glassmorphism Overlays */\r\n.glass-card {\r\n    background: rgba(255, 255, 255, 0.8);\r\n    -webkit-backdrop-filter: blur(10px);\r\n    backdrop-filter: blur(10px);\r\n}\r\n\r\n@media (max-width: 1024px) {\r\n    .main-grid {\r\n        grid-template-columns: 1fr;\r\n    }\r\n}"],"sourceRoot":""}]);
